window.getItemListInfo = function (referrer = document.referrer, origin = window.location.origin) {
  if (referrer === origin + '/' || referrer === origin || new RegExp(`^${origin}/[a-zA-Z-]{2,5}$`).test(referrer)) {
    return {
      item_list_id: 'HP',
      item_list_name: 'homepage',
    };
  } else if (referrer.includes('/products/')) {
    return {
      item_list_id: 'PDP',
      item_list_name: referrer.split('/products/')[1].split('/')[0].split('?')[0],
    };
  } else if (referrer.includes('/collections/')) {
    return {
      item_list_id: 'PLP',
      item_list_name: referrer.split('/collections/')[1].split('/')[0].split('?')[0],
    };
  } else if (referrer.includes('/search?')) {
    return {
      item_list_id: 'search',
      item_list_name: 'search_results',
    };
  } else if (referrer.includes('/cart')) {
    return {
      item_list_id: 'cart',
      item_list_name: 'cart',
    };
  } else if (referrer.includes('/apps/iwish')) {
    return {
      item_list_id: 'wishlist',
      item_list_name: 'wishlist',
    };
  } else
    return {
      item_list_id: 'other',
      item_list_name: 'other',
    };
};

function DatalayerEvents() {
  function getCookie(name) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if (parts.length === 2) return parts.pop().split(';').shift();
  }

  function addCommonInfo(eventBody) {
    // Improved item_list_name and item_list_id
    for (let i = 0; i < eventBody.ecommerce?.items?.length; i++) {
      if (
        eventBody.ecommerce.items[i].item_list_id === 'TBD' &&
        eventBody.ecommerce.items[i].item_list_name === 'TBD'
      ) {
        const listInfo = window.getItemListInfo();
        eventBody.ecommerce.items[i].item_list_id = listInfo.item_list_id;
        eventBody.ecommerce.items[i].item_list_name = listInfo.item_list_name;
      }
    }

    return {
      ...eventBody,
      referrer: document.referrer,
      full_url: window.location.href,
      user_properties: {
        ...eventBody.user_properties,
        session_id: getCookie('_shopify_s'),
        session_count: '',
      },
    };
  }

  // Expose utility function to push events from anywhere
  window.pushToDataLayer = function (eventDataOrElement) {
    try {
      let eventData;

      // Check if it's an element with data-datalayer-info attribute
      if (eventDataOrElement instanceof Element && eventDataOrElement.hasAttribute('data-datalayer-info')) {
        eventData = JSON.parse(eventDataOrElement.getAttribute('data-datalayer-info'));
      } else if (typeof eventDataOrElement === 'object') {
        // It's already an object
        eventData = eventDataOrElement;
      } else if (typeof eventDataOrElement === 'string' && eventDataOrElement.trim().startsWith('{')) {
        // It's a JSON string
        eventData = JSON.parse(eventDataOrElement);
      } else {
        return;
      }

      // Check if this event has more than 30 items
      const MAX_ITEMS_PER_EVENT = 30;
      if (eventData.ecommerce?.items?.length > MAX_ITEMS_PER_EVENT) {
        const allItems = eventData.ecommerce.items;

        // Split items into batches and push separate events
        for (let i = 0; i < allItems.length; i += MAX_ITEMS_PER_EVENT) {
          const batchItems = allItems.slice(i, i + MAX_ITEMS_PER_EVENT);

          const batchEventData = {
            ...eventData,
            ecommerce: {
              ...eventData.ecommerce,
              items: batchItems,
            },
          };

          const eventBody = addCommonInfo(batchEventData);

          window.dataLayer = window.dataLayer || [];
          window.dataLayer.push(eventBody);
        }
        return;
      }

      const eventBody = addCommonInfo(eventData);

      window.dataLayer = window.dataLayer || [];
      window.dataLayer.push(eventBody);
    } catch (e) {
      console.error('Error pushing to dataLayer:', e);
    }
  };

  function pushElementToDatalayer(element) {
    // Loop through all attributes that start with data-datalayer-info
    Array.from(element.attributes)
      .filter((attr) => attr.name.startsWith('data-datalayer-info'))
      .forEach((attr) => {
        window.pushToDataLayer(attr.value);
      });
  }

  function bindElementToDatalayer(element) {
    // Prevent double binding
    if (element.dataset.datalayerBinded === 'true') {
      return;
    }
    element.dataset.datalayerBinded = 'true';

    const eventsTypes = (element.getAttribute('data-datalayer-event') || 'click').split(',');

    eventsTypes.forEach((eventType) => {
      if (eventType == 'view') {
        const observer = new IntersectionObserver(
          (entries, observer) => {
            entries.forEach((entry) => {
              if (entry.isIntersecting) {
                pushElementToDatalayer(element);
                observer.unobserve(element);
                // Mark as tracked to avoid duplicate events
                element.dataset.datalayerTracked = 'true';
              }
            });
          },
          { root: null, rootMargin: '0px', threshold: 0.1 },
        );
        observer.observe(element);
      } else if (eventType) {
        element.addEventListener(eventType, function () {
          pushElementToDatalayer(element);
        });
      }
    });
  }

  function init() {
    // ALWAYS push pageview event FIRST if it exists on the main element
    const mainElement = document.querySelector('main[data-datalayer-info][data-datalayer-event="view"]');
    if (mainElement) {
      // Push pageview immediately as the first event
      pushElementToDatalayer(mainElement);
      // Mark it as tracked to avoid duplicate events later
      mainElement.dataset.datalayerTracked = 'true';
    }

    const elementsToBind = document.querySelectorAll('[data-datalayer-info]');

    elementsToBind.forEach((element) => {
      // Skip the main element since we already handled it
      if (element === mainElement) {
        element.dataset.datalayerBinded = 'true';
        return;
      }
      bindElementToDatalayer(element);
    });
  }

  // Customize property handling
  window.updateCustomizeProperty = function () {
    const customization = window.mappedStore?.['shared'];
    const hasCustomization = !!(
      customization?.customizationName?.length > 0 ||
      customization?.customizationNumber?.toString().length > 0 ||
      (customization?.currentAddOns && customization?.currentAddOns.length > 0)
    );

    // This one is for the cart properties (checkout events)
    const input = document.querySelector('.shopify-section--main-product input[name="properties[_customize]"]');
    if (input) {
      input.value = hasCustomization;
    }

    // This one is for the data layer buy buttons
    document.querySelectorAll('div[data-block-type="buy-buttons"] div[data-datalayer-info]').forEach((element) => {
      try {
        const eventData = JSON.parse(element.getAttribute('data-datalayer-info'));
        if (eventData && eventData.ecommerce && eventData.ecommerce.items) {
          eventData.ecommerce.items = eventData.ecommerce.items.map((product) => {
            return {
              ...product,
              item_customize: hasCustomization.toString(),
            };
          });
          element.setAttribute('data-datalayer-info', JSON.stringify(eventData));
        }
      } catch (e) {
        // Silently fail
      }
    });
  };

  // Make bindCustomizationButton available globally
  window.bindCustomizationButton = function (button) {
    // Prevent double binding
    if (button.dataset.customizationBound === 'true') {
      return;
    }
    button.dataset.customizationBound = 'true';

    button.addEventListener('mouseenter', window.updateCustomizeProperty);
    button.addEventListener('touchstart', window.updateCustomizeProperty, { passive: true });
    button.addEventListener('click', () => {
      const element = document.querySelector('div[data-block-type="buy-buttons"] div[data-datalayer-info]');
      if (element) {
        window.pushToDataLayer(element);
      }
    });
  };

  // Bind existing buttons on initialization
  [
    ...document.querySelectorAll('.product-customization-add-to-cart'),
    ...document.querySelectorAll('.product-customization-drawer__footer button'),
  ].forEach((button) => {
    window.bindCustomizationButton(button);
  });
  // End customize property handling

  init();

  // Quantity selector dataLayer event handler
  function initQuantitySelectorsDataLayer() {
    const handleDataLayerEvent = (event) => {
      const select = event.target;
      const selectedOption = select.options[select.selectedIndex];

      if (selectedOption && selectedOption.hasAttribute('data-datalayer-info') && window.pushToDataLayer) {
        window.pushToDataLayer(selectedOption);
      }
    };

    const hookQuantitySelectors = () => {
      document.querySelectorAll('.quantity-selector__select').forEach((select) => {
        // Prevent double binding
        if (select.dataset.datalayerQuantityBound === 'true') {
          return;
        }
        select.dataset.datalayerQuantityBound = 'true';

        select.addEventListener('change', handleDataLayerEvent);
      });
    };

    hookQuantitySelectors();
  }

  initQuantitySelectorsDataLayer();
}

document.addEventListener('DOMContentLoaded', function () {
  DatalayerEvents();

  // Quantity selector dataLayer event handler for dynamically added elements
  const handleQuantitySelectorDataLayerEvent = (event) => {
    const select = event.target;
    const selectedOption = select.options[select.selectedIndex];

    if (selectedOption && selectedOption.hasAttribute('data-datalayer-info') && window.pushToDataLayer) {
      window.pushToDataLayer(selectedOption);
    }
  };

  const hookQuantitySelector = (select) => {
    // Prevent double binding
    if (select.dataset.datalayerQuantityBound === 'true') {
      return;
    }
    select.dataset.datalayerQuantityBound = 'true';

    select.addEventListener('change', handleQuantitySelectorDataLayerEvent);
  };

  // Watch for dynamically added elements (e.g., product-recommendations, recently-viewed-products)
  const observer = new MutationObserver(function (mutations) {
    mutations.forEach(function (mutation) {
      mutation.addedNodes.forEach(function (node) {
        // Check if the added node has data-datalayer-info or contains elements with it
        if (node.nodeType === Node.ELEMENT_NODE) {
          if (node.hasAttribute && node.hasAttribute('data-datalayer-info')) {
            bindElementToDatalayer(node);
          } else if (node.querySelectorAll) {
            const newElements = node.querySelectorAll('[data-datalayer-info]');
            if (newElements.length > 0) {
              newElements.forEach(function (element) {
                bindElementToDatalayer(element);
              });
            }

            // Check for quantity selectors
            const newQuantitySelectors = node.querySelectorAll('.quantity-selector__select');
            if (newQuantitySelectors.length > 0) {
              newQuantitySelectors.forEach(function (select) {
                hookQuantitySelector(select);
              });
            }

            // Check for customization buttons
            const newCustomizationButtons = [
              ...node.querySelectorAll('.product-customization-add-to-cart'),
              ...node.querySelectorAll('.product-customization-drawer__footer button'),
            ];
            if (newCustomizationButtons.length > 0) {
              newCustomizationButtons.forEach(function (button) {
                window.bindCustomizationButton(button);
              });
            }
          }
        }
      });
    });
  });

  // Observe the entire document for added nodes
  observer.observe(document.body, {
    childList: true,
    subtree: true,
  });

  // Make bindElementToDatalayer available globally for the observer
  window.bindElementToDatalayer = function (element) {
    // Prevent double binding
    if (element.dataset.datalayerBinded === 'true') {
      return;
    }
    element.dataset.datalayerBinded = 'true';

    const eventsTypes = (element.getAttribute('data-datalayer-event') || 'click').split(',');

    eventsTypes.forEach((eventType) => {
      if (eventType == 'view') {
        // Check if element was already tracked in this session
        if (element.dataset.datalayerTracked === 'true') {
          return;
        }

        const observer = new IntersectionObserver(
          (entries, observer) => {
            entries.forEach((entry) => {
              if (entry.isIntersecting) {
                window.pushToDataLayer(element);
                observer.unobserve(element);
                // Mark as tracked to avoid duplicate events
                element.dataset.datalayerTracked = 'true';
              }
            });
          },
          { root: null, rootMargin: '0px', threshold: 0.1 },
        );
        observer.observe(element);
      } else if (eventType) {
        element.addEventListener(eventType, function () {
          window.pushToDataLayer(element);
        });
      }
    });
  };
});

document.addEventListener('theme:loading:end', function () {
  DatalayerEvents();
});
